bool gr_large_grf(sycl::queue* q) {
    static const bool v = [q] {
        const char* e = std::getenv("STRATA_GR_LARGE_GRF");
        if (e != nullptr) return std::atoi(e) != 0;
        return strata::intel_gpu_gen(q->get_device()) == strata::IntelGpuGen::Alchemist;
    }();
    return v;
}
